#!/usr/bin/env python3
"""Generates testdata/invite-vectors.tsv — golden invite codes for the
Android <-> Desktop interop tests (KL-13).

This is a THIRD, independent implementation of the documented wire format
(see the "Wire format" comment in either InviteCodeManager.kt): Python +
the `cryptography` package, no Kotlin code shared with either client.
Both clients' tests read the same TSV and must parse every row identically.

Keys are throwaway and discarded: the vectors are public data and no private
key is stored anywhere. Re-running produces different (equally valid)
vectors; the committed file is the reference. Needs: pip install cryptography
"""
import base64, hashlib, os, struct, sys
from cryptography.hazmat.primitives.asymmetric import ec
from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric.utils import decode_dss_signature

TS = 1760000000  # fixed: 2025-10-09; the vectors are intentionally "expired"


def b64u(b):
    return base64.urlsafe_b64encode(b).rstrip(b"=").decode()


def build(name_bytes, ts=TS, version=3, want_sig_len=None, key=None):
    """Returns (payload, fp_hex, nonce_hex, tag_hex, der_r_len, der_s_len)."""
    while True:
        k = key or ec.generate_private_key(ec.SECP256R1())
        x509 = k.public_key().public_bytes(
            serialization.Encoding.DER, serialization.PublicFormat.SubjectPublicKeyInfo)
        ecpoint = x509[-65:]
        fp = hashlib.sha256(x509).digest()[:8]
        nonce, tag = os.urandom(8), os.urandom(16)
        pre = bytes([version]) + struct.pack(">I", ts) + nonce + tag + fp + ecpoint \
            + bytes([len(name_bytes)]) + name_bytes
        der = k.sign(pre, ec.ECDSA(hashes.SHA256()))
        r, s = decode_dss_signature(der)
        rl, sl = (r.bit_length() + 7) // 8, (s.bit_length() + 7) // 8
        if want_sig_len and (rl, sl) not in want_sig_len:
            if key: raise SystemExit("cannot force sig shape with fixed key")
            continue
        raw = r.to_bytes(32, "big") + s.to_bytes(32, "big")
        return pre + raw, fp.hex().upper(), nonce.hex().upper(), tag.hex(), rl, sl, pre, ecpoint


rows = []


def add(id_, payload=None, code=None, parse_ok=1, fp="", nonce="", tag="", name=b"", ts=TS, sig_valid=0, note=""):
    if code is None:
        code = "bc:" + b64u(payload)
    rows.append([id_, code, str(parse_ok), fp, nonce, tag, name.hex(), str(ts if parse_ok else 0),
                 str(sig_valid if parse_ok else 0), note])


def valid(id_, name, note, **kw):
    p, fp, n, t, rl, sl, *_ = build(name, **kw)
    add(id_, payload=p, fp=fp, nonce=n, tag=t, name=name, sig_valid=1, note=note)
    return p


valid("ascii-name", b"Alice", "plain ASCII display name")
valid("unicode-name", "Анна 🔑".encode(), "multi-byte UTF-8 name")
valid("empty-name", b"", "zero-length name (minimum payload size)")
valid("max-name-255", b"x" * 255, "255-byte name (length byte 0xFF)")
# DER r/s shorter or longer than 32 bytes => exercises padOrTrim32 / derEncodeInt
valid("sig-r-short", b"short-r", "signature whose DER r is < 32 bytes", want_sig_len={(31, 32), (30, 32)})
valid("sig-s-short", b"short-s", "signature whose DER s is < 32 bytes", want_sig_len={(32, 31), (32, 30)})

base = build(b"Mallory")
p, fp, n, t, *_ = base
# negatives
add("trailing-byte", payload=p + b"\x7f", parse_ok=0, note="junk after signature must be rejected")
add("version-02-legacy", payload=bytes([2]) + p[1:], parse_ok=0, note="legacy 0x02 (no mailbox tag) rejected")
add("version-04-unknown", payload=bytes([4]) + p[1:], parse_ok=0, note="unknown future version rejected")
add("too-short", payload=os.urandom(10), parse_ok=0, note="below structural minimum")
add("no-prefix", code=b64u(p), parse_ok=0, note="missing bc: prefix")
add("bad-base64", code="bc:!!!not base64!!!", parse_ok=0, note="undecodable body")
add("empty-body", code="bc:", parse_ok=0, note="prefix only")
# parses, signature must NOT verify
bad = bytearray(p); bad[-1] ^= 1
add("tampered-signature", payload=bytes(bad), fp=fp, nonce=n, tag=t, name=b"Mallory", sig_valid=0,
    note="parses, but signature is invalid")
bad = bytearray(p); bad[1 + 4 + 8 + 16 + 8 + 20] ^= 1  # flip a byte inside the EC point
add("tampered-key", payload=bytes(bad), fp=fp, nonce=n, tag=t, name=b"Mallory", sig_valid=0,
    note="EC point altered: fingerprint no longer matches / sig invalid")

out = os.path.join(os.path.dirname(os.path.abspath(__file__)), "invite-vectors.tsv")
with open(out, "w", encoding="utf-8", newline="\n") as f:
    f.write("# Golden invite codes — generated by gen_invite_vectors.py (independent Python implementation).\n")
    f.write("# Read by app/src/test/.../InviteVectorsTest.kt and desktop/src/test/.../InviteVectorsTest.kt.\n")
    f.write("# Timestamps are fixed (2025-10-09) so every row is EXPIRED today: the tests check parse output and\n")
    f.write("# an independent ECDSA verification, and that verifyInviteCode() rejects them (7-day TTL).\n")
    f.write("# columns: id<TAB>code<TAB>parse_ok<TAB>fingerprint<TAB>nonce<TAB>mailbox_tag<TAB>name_utf8_hex<TAB>timestamp<TAB>sig_valid<TAB>note\n")
    for r in rows:
        f.write("\t".join(r) + "\n")
print("wrote", out, len(rows), "rows")
